+typedef struct {
+  CK_SESSION_HANDLE session;
+  CK_BYTE *data;
+  CK_ULONG dataLen;
+  CK_RV rv;
+  CNK_PKCS11_SESSION *held;
+  atomic_bool entered;
+  atomic_bool updateStarted;
+} DigestThreadContext;
+
+typedef struct {
+  CK_SESSION_HANDLE session;
+  CK_RV rv;
+  CNK_PKCS11_SESSION *held;
+  atomic_bool entered;
+} FindThreadContext;
