+static char *cnk_trim_ascii(char *value) {
+  if (value == NULL)
+    return NULL;
+
+  while (*value != '\0' && isspace((unsigned char)*value))
+    value++;
+
+  char *end = value + strlen(value);
+  while (end > value && isspace((unsigned char)end[-1]))
+    *--end = '\0';
+  return value;
