+  fi
+
+  MEM9_PLUGIN_USER_AGENT="mem9-plugin/kimi-code/${version}"
+  printf '%s\n' "${MEM9_PLUGIN_USER_AGENT}"
+}
+
+mem9_hook_get_string() {
