+  if [[ -z "${auth_api_key}" ]]; then
+    return 1
+  fi
+
+  MEM9_API_KEY="${auth_api_key}"
+  MEM9_AUTH_SOURCE="credentials_file"
+
+  [[ -n "${MEM9_API_KEY}" ]] || return 1
+  export MEM9_API_URL MEM9_AGENT_ID MEM9_WRITER_ID MEM9_API_KEY
